    },
    [10112] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 107000,
      role2 = 101103,
      role3 = 101202,
      sentence = "But I didn't reach out for the box. Instead, I looked up at him.",
      next = {10113}
    },
    [10113] = {
