    },
    [10121] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 107000,
      role2 = 101103,
      role3 = 101202,
      sentence = "Meeting my hopeful gaze, he flashed a relaxed smile and fingered the edge of the box with his thumb, then said in a deep voice:",
