    },
    [10122] = {
      beijing = 1012,
      dialog = 2,
      idx = 1,
      male = 1,
      music = "33_Wedding",
      renming = "Victor",
      renwu = "npc",
      role1 = 107000,
      role2 = 101101,
      role3 = 101202,
      sentence = "I am not a prophet, but whatever I say, I'll be sure to make it come true.",
      voice = 1,
      next = {10123}
    },
    [10123] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 107000,
      role2 = 101101,
      role3 = 101202,
      sentence = "He paused, then looked at me.",
      next = {10124}
    },
    [10124] = {
      beijing = 1012,
      dialog = 2,
      idx = 1,
      male = 1,
      music = "33_Wedding",
      renming = "Victor",
      renwu = "npc",
      role1 = 107000,
      role2 = 101103,
      role3 = 101202,
      sentence = "In this coming year, there will, as always, be things that you like. You will work hard and press on doggedly every step of the way.",
      voice = 1,
      next = {10125}
    },
    [10125] = {
      beijing = 1012,
      dialog = 2,
      idx = 1,
      male = 1,
      music = "33_Wedding",
      renming = "Victor",
      renwu = "npc",
      role1 = 107000,
      role2 = 101103,
      role3 = 101202,
      sentence = "Most importantly, no matter where you go or what you see, or what you go through—",
      voice = 1,
      next = {10126}
    },
    [10126] = {
      beijing = 1012,
      dialog = 2,
      idx = 1,
      male = 1,
      music = "33_Wedding",
      renming = "Victor",
      renwu = "npc",
      role1 = 107000,
      role2 = 101103,
      role3 = 101202,
      sentence = "—at every moment, you will know the feeling of love and being loved. There will always be someone whose heart beats in time with yours, and who understands all your joys and sorrows.",
      voice = 1,
      next = {10127}
    },
    [10127] = {
      beijing = 1012,
      dialog = 2,
      idx = 1,
      male = 1,
      music = "33_Wedding",
      renming = "Victor",
      renwu = "npc",
      role1 = 107000,
      role2 = 101103,
      role3 = 101202,
      sentence = "And there can be nothing more precious than this in the whole world.",
      voice = 1,
      next = {10128}
    },
    [10128] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 107000,
      role2 = 101103,
      role3 = 101202,
      sentence = "After saying these words, his brow softened, as if it would melt.",
      next = {10129}
    },
    [10129] = {
      beijing = 1012,
      dialog = 2,
      idx = 1,
      male = 1,
      music = "33_Wedding",
      renming = "Victor",
      renwu = "npc",
      role1 = 107000,
      role2 = 101108,
      role3 = 101202,
      sentence = "Don’t worry. I'll be by your side and give all of this to you.",
      voice = 1,
      next = {10130}
    },
    [10130] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 107000,
      role2 = 101108,
      role3 = 101202,
      sentence = "I was a bit stunned, but Victor nonetheless pulled my hand to him and opened the box. Then he took out the gift inside and placed it in my palm.",
      next = {10131}
    },
    [10131] = {
      beijing = 1012,
