      music = "33_Wedding",
      renwu = "npc",
      role1 = 107000,
      role2 = 101108,
      role3 = 101202,
      sentence = "Then with a smile in his eyes, as if nothing could be more normal, he sang that familiar song to me.",
      next = {10132}
    },
    [10132] = {
      beijing = 1012,
      dialog = 2,
      idx = 1,
      male = 1,
      music = "33_Wedding",
      renming = "Victor",
      renwu = "npc",
      role1 = 107000,
      role2 = 101108,
      role3 = 101202,
      sentence = "Happy birthday to you, happy birthday to you, happy birthday to yooo-ou, happy birthday to you.",
