      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 107000,
      role2 = 101108,
      role3 = 101202,
      sentence = "Silence filled the room, and the only thing I saw was this person standing before me, as if amidst all the flowing of time, he was the only eternal, unchanging thing.",
