      role1 = 235000,
      role2 = 201105,
      role3 = 201201,
      role5 = 235404,
      ruchang = -1,
      sentence = "Lucien sat beside me, propping himself up on a hand and watching my motions with a smiling face.",
      next = {10218}
    },
    [10218] = {
