      music = "33_Wedding",
      renming = "Lucien",
      renwu = "npc",
      role1 = 235000,
      role2 = 201105,
      role3 = 201201,
      role5 = 235404,
      sentence = "I've been thinking for a long time about how I should celebrate this day with you this year.",
      voice = 1,
      next = {10219}
    },
