      renming = "Lucien",
      renwu = "npc",
      role1 = 235000,
      role2 = 201105,
      role3 = 201201,
      role5 = 235404,
      sentence = "And at the very end, I suddenly realized that this day has become so important to me, that I look forward to its coming as much as you.",
