      next = {10221}
    },
    [10221] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 235000,
      role2 = 201105,
      role3 = 201201,
      role5 = 235404,
      sentence = "Lucien said this with a smile. Meanwhile, his hand that was usually holding pen and paper was now smudged with cream, which looked a bit incongruous, but also endearing.",
