      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 235000,
      role2 = 201105,
      role3 = 201201,
      role5 = 235404,
      sentence = "I spoke sincerely to him, then after a bit of thought, started to laugh.",
