      music = "33_Wedding",
      renwu = "npc",
      role1 = 235000,
      role2 = 201105,
      role3 = 201201,
      role5 = 235404,
      sentence = "I threw it out there like a joke, but Lucien's eyes squinted in a smile.",
      next = {10226}
    },
    [10226] = {
      beijing = 1012,
      dialog = 2,
      idx = 2,
