      dialog = 2,
      idx = 2,
      male = 2,
      music = "33_Wedding",
      renming = "Lucien",
      renwu = "npc",
      role1 = 235000,
      role2 = 201105,
      role3 = 201201,
      role5 = 235404,
      sentence = "It was failure after failure in the beginning, but luckily in the end, I succeeded.",
