      renming = "Lucien",
      renwu = "npc",
      role1 = 235000,
      role2 = 201105,
      role3 = 201201,
      role5 = 235404,
      sentence = "But the luckiest thing of all is that I'm the one who gets to celebrate this day with you.",
      voice = 1,
