      role1 = 235000,
      role2 = 201105,
      role3 = 201201,
      role5 = 235404,
      sentence = "The night washed over me like an ocean. Right now, my entire world was just Lucien's voice, Lucien's face, and Lucien's scent.",
      next = {10238}
    },
    [10238] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 235000,
      role2 = 201103,
      role3 = 201202,
      role5 = 235404,
      sentence = "Seeing how I looked, he couldn't help but chuckle. Then he reached out and drew me into his embrace, enveloping me with the scent of fresh grass.",
      next = {10239}
    },
    [10239] = {
      beijing = 1012,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "33_Wedding",
      renming = "Lucien",
      renwu = "npc",
      role1 = 235000,
      role2 = 201105,
      role3 = 201201,
      role5 = 235404,
      ruchang = 9,
      sentence = "Don't forget to hold my hand this year, okay?",
      voice = 1,
      next = {10240}
    },
    [10240] = {
      beijing = 1012,
      dialog = 3,
      game_params = 1512,
      game_type = "Share",
      music = "33_Wedding",
      renwu = "npc",
      next = {2}
    },
    [10301] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "But when I opened the door, I didn't see Kiro. All I saw was a room filled with drifting, colored balloons and a speaker playing Happy Birthday on a loop.",
      next = {10302}
    },
    [10302] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "I knew Kiro must be hiding somewhere, but I didn't search for him on purpose and just walked over to inspect the speaker.",
      next = {10303}
    },
    [10303] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "But then I suddenly heard the sound of a confetti popper exploding behind me.",
      next = {10304}
    },
    [10304] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "I turned to see streamers fill the air and Kiro standing behind me. He was holding the popper in his hand and beaming at me with a humongous smile.",
      next = {10305}
    },
    [10305] = {
      beijing = 1012,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 319000,
      role2 = 301101,
      role3 = 301203,
      ruchang = -1,
      sentence = "Happy birthday to the cutest girl in the world, Miss Chips!",
      voice = 1,
      next = {10306}
    },
    [10306] = {
      beijing = 1012,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 319000,
      role2 = 301101,
      role3 = 301201,
      sentence = "Your personal Happy Birthday singer has arrived. Would you like to start playing the birthday song now?",
      voice = 1,
      next = {10307}
    },
    [10307] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 319000,
      role2 = 301101,
      role3 = 301201,
      sentence = "As I held an orange balloon in one hand, I smiled and said:",
      next = {10308}
    },
    [10308] = {
      beijing = 1012,
      dhead = 114,
      dialog = 1,
      music = "33_Wedding",
      renming = "$u",
      renwu = "npc",
      role1 = 319000,
      role2 = 301101,
      role3 = 301201,
      sentence = "Well—Okay, I'll play one Happy Birthday.",
      next = {10309}
    },
    [10309] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 319000,
      role2 = 301114,
      role3 = 301201,
      sentence = "Kiro cleared his throat, and the happy music played along to his sonorous singing voice.",
      next = {10310}
    },
    [10310] = {
      beijing = 1012,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 319000,
      role2 = 301106,
      role3 = 301201,
      sentence = "Happy birthday to you, happy birthday to you, happy birthday to yooo-ou, happy birthday to you.",
      voice = 1,
      next = {10311}
    },
    [10311] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 319000,
      role2 = 301101,
      role3 = 301201,
      roleanim = 1.1,
      sentence = "He swayed his head back and forth as he sang, which made me giggle uncontrollably. Then Kiro stretched out his arms and hugged me.",
      next = {10312}
    },
    [10312] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 319000,
      role2 = 301101,
      role3 = 301201,
      roleanim = 1.1,
      sentence = "He lowered his head, batted his long eyelashes, and looked me in the eyes.",
      next = {10313}
    },
    [10313] = {
      beijing = 1012,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 319000,
      role2 = 301101,
      role3 = 301207,
      roleanim = 1.1,
      sentence = "What are you laughing at, Miss Chips? Did I not do a good job singing?",
      voice = 1,
      next = {10314}
    },
    [10314] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 319000,
      role2 = 301101,
      role3 = 301201,
      roleanim = 1.1,
      sentence = "I quickly shook my head.",
      next = {10315}
    },
    [10315] = {
      beijing = 1012,
      dhead = 107,
      dialog = 1,
      music = "33_Wedding",
      renming = "$u",
      renwu = "npc",
      role1 = 319000,
      role2 = 301101,
      role3 = 301201,
      roleanim = 1.1,
      sentence = "No, your singing was great.",
      next = {10316}
    },
    [10316] = {
      beijing = 1012,
      dhead = 114,
      dialog = 1,
      music = "33_Wedding",
      renming = "$u",
      renwu = "npc",
      role1 = 319000,
      role2 = 301101,
      role3 = 301201,
      roleanim = 1.1,
      ruchang = 9,
      sentence = "It was just so cute. I kept thinking of a little bobblehead teddy bear, hahahaha.",
      next = {10317}
    },
    [10317] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "Just as I was laughing out loud, I suddenly felt a soft pair of lips plant themselves on my forehead. I looked up in a bit of a daze—",
      next = {10318}
    },
    [10318] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "—to see Kiro with a contented smile on his face.",
      next = {10319}
    },
    [10319] = {
      beijing = 1012,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 319000,
      role2 = 301102,
      role3 = 301201,
      roleanim = 1.1,
      ruchang = -1,
      sentence = "A teddy bear can't do all of this, and he wouldn't sit in a room blowing up balloons all afternoon to celebrate your birthday.",
      voice = 1,
      next = {10320}
    },
    [10320] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 319000,
      role2 = 301102,
      role3 = 301201,
      roleanim = 1.1,
      sentence = "My gaze shifted to the hovering balloons filling up the room. It was kind of funny.",
      next = {10321}
    },
    [10321] = {
      beijing = 1012,
      dhead = 107,
      dialog = 1,
      music = "33_Wedding",
      renming = "$u",
      renwu = "npc",
      role1 = 319000,
      role2 = 301101,
      role3 = 301201,
      roleanim = 1.1,
      sentence = "You blew up way too many. I feel like they're going to fly out of the room.",
      next = {10322}
    },
    [10322] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 319000,
      role2 = 301102,
      role3 = 301201,
      roleanim = 1.1,
      sentence = "Kiro grabbed a pink balloon, just as bouncy as the tone of his voice.",
      next = {10323}
    },
    [10323] = {
      beijing = 1012,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 319000,
      role2 = 301102,
      role3 = 301201,
      roleanim = 1.1,
      sentence = "Not happening.",
      voice = 1,
      next = {10324}
    },
    [10324] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 319000,
      role2 = 301102,
      role3 = 301201,
      roleanim = 1.1,
      sentence = "His smiling eyes were full of dazzling light.",
      next = {10325}
    },
    [10325] = {
      beijing = 1012,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 319000,
      role2 = 301101,
      role3 = 301201,
      roleanim = 1.1,
      sentence = "I specially chose these balloons.",
      voice = 1,
      next = {10326}
    },
    [10326] = {
      beijing = 1012,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 319000,
      role2 = 301101,
      role3 = 301201,
      roleanim = 1.1,
      sentence = "Each one represents a time you and I spent together, and in each one, I hid a slip of paper.",
      voice = 1,
      next = {10327}
    },
    [10327] = {
      beijing = 1012,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 319000,
      role2 = 301101,
      role3 = 301201,
      roleanim = 1.1,
      sentence = "There are some happy ones when we had fun together, or some when you were backstage pumping me up before a show, but each and every time was full of splendor.",
      voice = 1,
      next = {10328}
    },
    [10328] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 319000,
      role2 = 301101,
      role3 = 301202,
      roleanim = 1.1,
      sentence = "He started to become serious.",
      next = {10329}
    },
    [10329] = {
      beijing = 1012,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 319000,
      role2 = 301101,
      role3 = 301202,
      roleanim = 1.1,
      sentence = "Just like you, Miss Chips. Full of splendor.",
      voice = 1,
      next = {10330}
    },
    [10330] = {
      beijing = 1012,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 319000,
      role2 = 301101,
      role3 = 301202,
      roleanim = 1.1,
      sentence = "I've witnessed all the things you've been through in the past year, the roads you've had to travel, and I know exactly how wonderful you are.",
      voice = 1,
      next = {10331}
    },
    [10331] = {
      beijing = 1012,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 319000,
      role2 = 301101,
      role3 = 301202,
      roleanim = 1.1,
      sentence = "You are my only treasure in the whole world. And on your birthday, I want to make this wish for you—",
      voice = 1,
      next = {10332}
    },
    [10332] = {
      beijing = 1012,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 319000,
      role2 = 301101,
      role3 = 301201,
      roleanim = 1.1,
      ruchang = 9,
      sentence = "—May you always be free and happy, and always live a colorful, splendid life.",
      voice = 1,
      next = {10333}
    },
    [10333] = {
      beijing = 1012,
      dialog = 3,
      game_params = 1513,
      game_type = "Share",
      music = "33_Wedding",
      renwu = "npc",
      next = {2}
    },
    [10401] = {
      beijing = 0,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "I walked in hesitantly and was about to feel around for the light, when suddenly a voice sounded before me.",
      next = {10402}
    },
    [10402] = {
      beijing = 0,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "33_Wedding",
      renming = "Gavin",
      renwu = "npc",
      sentence = "Happy birthday to you, happy birthday to you! Happy birthday to you, happy birthday to you...",
      voice = 1,
      next = {10403}
    },
    [10403] = {
      beijing = 0,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "A man's clear, low voice sung out in the darkness, accompanied by a candle flickering with light.",
      next = {10404}
    },
    [10404] = {
      beijing = 0,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403203,
      role5 = 436401,
      ruchang = -1,
      sentence = "Gavin stood before me, his amber eyes full of earnest sincerity.",
      next = {10405}
    },
    [10405] = {
      beijing = 0,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "33_Wedding",
      renming = "Gavin",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403203,
      role5 = 436401,
      sentence = "Happy birthday, $u.",
      voice = 1,
      next = {10406}
    },
    [10406] = {
      beijing = 0,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "33_Wedding",
      renming = "Gavin",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403203,
      role5 = 436401,
      ruchang = 9,
      sentence = "This is already your fourth birthday with me, but the most important birthday wishes are still to come.",
      voice = 1,
      next = {10407}
    },
    [10407] = {
      beijing = 1012,
      bganim = 1,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "With that, he turned on the light. The room had clearly been decorated, with colorful streamers and a big \"Happy Birthday\" banner.",
      next = {10408}
    },
    [10408] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403203,
      role5 = 436401,
      ruchang = -1,
      sentence = "And in his arms, Gavin held a bouquet of flowers in full bloom.",
      next = {10409}
    },
    [10409] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403203,
      role5 = 436401,
      sentence = "The light fell on the tender flower petals, making everything look so serene and peaceful, as if my heart suddenly felt at home.",
      next = {10410}
    },
    [10410] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403203,
      role5 = 436401,
      sentence = "He handed the bouquet to me, and I smiled as I took it, brushing off beads of dew from the leaves.",
      next = {10411}
    },
    [10411] = {
      beijing = 1012,
      dhead = 107,
      dialog = 1,
      music = "33_Wedding",
      renming = "$u",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403203,
      role5 = 436401,
      sentence = "Where did you get the idea to buy flowers?",
      next = {10412}
    },
    [10412] = {
      beijing = 1012,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "33_Wedding",
      renming = "Gavin",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403203,
      role5 = 436401,
      sentence = "Your birthday only comes once a year. Of course I've gotta do something special.",
      voice = 1,
      next = {10413}
    },
    [10413] = {
      beijing = 1012,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "33_Wedding",
      renming = "Gavin",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403207,
      role5 = 436401,
      sentence = "After last year's experience, this year I got right to setting everything up.",
      voice = 1,
      next = {10414}
    },
    [10414] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403207,
      role5 = 436401,
      sentence = "With that, he started to laugh, and his eyes twinkled with satisfaction.",
      next = {10415}
    },
    [10415] = {
      beijing = 1012,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "33_Wedding",
      renming = "Gavin",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403207,
      role5 = 436401,
      sentence = "We've spent a lot of holidays together, and every one feels a little different. But I look forward to this day more than any other.",
      voice = 1,
      next = {10416}
    },
    [10416] = {
      beijing = 1012,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "33_Wedding",
      renming = "Gavin",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403207,
      role5 = 436401,
      sentence = "Because today is your very own special day.",
      voice = 1,
      next = {10417}
    },
    [10417] = {
      beijing = 1012,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "33_Wedding",
      renming = "Gavin",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403207,
      role5 = 436401,
      sentence = "And also the day I most want to spend with you.",
      voice = 1,
      next = {10418}
    },
    [10418] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403207,
      role5 = 436401,
      sentence = "I looked at Gavin smiling and staring into my eyes.",
      next = {10419}
    },
    [10419] = {
      beijing = 1012,
      dhead = 101,
      dialog = 1,
      music = "33_Wedding",
      renming = "$u",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403207,
      role5 = 436401,
      sentence = "Gavin, I'm happy today. So, so, incredibly happy.",
      next = {10420}
    },
    [10420] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403207,
      role5 = 436401,
      sentence = "When Gavin heard my words, his eyes lit up with mirth.",
      next = {10421}
    },
    [10421] = {
      beijing = 1012,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "33_Wedding",
      renming = "Gavin",
      renwu = "npc",
      role1 = 436000,
      role2 = 403110,
      role3 = 403203,
      role5 = 436401,
      sentence = "But I still feel like something's missing.",
      voice = 1,
      next = {10422}
    },
    [10422] = {
      beijing = 1012,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "33_Wedding",
      renming = "Gavin",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403203,
      role5 = 436401,
      sentence = "I want to give the most beautiful things in this world to you, so that there is only a carefree smile on your face.",
      voice = 1,
      next = {10423}
    },
    [10423] = {
      beijing = 1012,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "33_Wedding",
      renming = "Gavin",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403203,
      role5 = 436401,
      sentence = "I also want to keep you safe, so that you can have smooth sailing no matter what, unaffected by the wind and rain.",
      voice = 1,
      next = {10424}
    },
    [10424] = {
      beijing = 1012,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "33_Wedding",
      renming = "Gavin",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403207,
      role5 = 436401,
      sentence = "There's too much I want to give you, so much that... this whole life won't be enough.",
      voice = 1,
      next = {10425}
    },
    [10425] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403207,
      role5 = 436401,
      sentence = "If the significance of celebrating a birthday is to say to the world, I exist, I've loved, I've laughed... then in this moment, I felt the power of this witness.",
      next = {10426}
    },
    [10426] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403207,
      role5 = 436401,
      sentence = "This power came half from myself, and half from this person before me.",
      next = {10427}
    },
    [10427] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 436000,
      role2 = 403111,
      role3 = 403207,
      role5 = 436401,
      sentence = "He's the one who made me know what it feels like to be cherished, and he's the one who made me understand all a person's joy and anger and sorrow can be so meaningful.",
