      music = "33_Wedding",
      renwu = "npc",
      role1 = 703000,
      role2 = 703101,
      role3 = 703203,
      roleanim = 1.1,
      sentence = "His glittering eyes drooped down to look at me, and there was a smile on his lips, but his gaze was entirely sincere.",
