      renwu = "npc",
      role1 = 703000,
      role2 = 703101,
      role3 = 703203,
      roleanim = 1.1,
      sentence = "I just thought, since you're the type of person that doesn't like to make a big deal out of things, it was quite a surprise that you would go all out to get these tickets for me.",
