    },
    [10523] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "We'd been to a lot of places together, like a packed and rocking Live House, or the noisy Rock 'n Roll Amusement Park, or the bustling city streets.",
