    },
    [10524] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "Sometimes the things he said would get drowned out by the background noise, but in this moment, when it was just us face to face, everything around was still and silent.",
