    },
    [10526] = {
      beijing = 1012,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "Just when I thought this simple little birthday ceremony was over, Shaw suddenly raised his head and looked at me.",
      next = {10527}
    },
