      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 703000,
      role2 = 703101,
      role3 = 703202,
      sentence = "The melody was still playing, and I could see my reflection clearly in his eyes, plain as day.",
      next = {10529}
    },
    [10529] = {
