      renming = "Shaw",
      renwu = "npc",
      role1 = 703000,
      role2 = 703101,
      role3 = 703202,
      sentence = "I don't like to make a big deal out of things, but there's a saying that I happen to agree with, that some people exist to make you break your own rules.",
      voice = 1,
      next = {10530}
    },
    [10530] = {
